import AppKit
import GHNotifCore
import UserNotifications

/// GitHub timeline-style badges (Octicon on a coloured circle), generated by scripts/generate-notification-badges.swift.
enum NotificationIcon {
    static func attachment(for event: AlertEvent) -> UNNotificationAttachment? {
        guard let source = url(for: event) else { return nil }
        // The system moves attachment files into its own store, so each notification gets a fresh copy.
        let copy = FileManager.default.temporaryDirectory.appendingPathComponent("ghnotif-\(UUID().uuidString).png")
        do {
            try FileManager.default.copyItem(at: source, to: copy)
            return try UNNotificationAttachment(identifier: event.rawValue, url: copy)
        } catch {
            NSLog("GHNotif: nie udało się dołączyć ikony: %@", error.localizedDescription)
            return nil
        }
    }

    static func image(for event: AlertEvent) -> NSImage {
        url(for: event).flatMap(NSImage.init(contentsOf:)) ?? NSImage()
    }

    private static func url(for event: AlertEvent) -> URL? {
        AppResources.bundle.url(forResource: "badge-\(event.rawValue)", withExtension: "png")
    }
}
